-- PKTracker: базовая схема (PLAN.md §3.2, §7.1).
-- Отличия от плана:
--  * hands.hand_pk — GENERATED BY DEFAULT (а не ALWAYS): ключи выделяются пачкой из последовательности
--    и пишутся через COPY BINARY, который не умеет OVERRIDING SYSTEM VALUE.
--  * import_state.offset → byte_offset (OFFSET — зарезервированное слово).
--  * hand_decisions.stack_bucket — измерение агрегата нужно для селективного ребилда без повторного парсинга.
--  * hand_raw.codec — формат сжатия тела (0 = zstd без словаря).

CREATE TABLE room (
    room_id   smallint PRIMARY KEY,
    code      text NOT NULL UNIQUE,
    network   text NOT NULL
);
INSERT INTO room (room_id, code, network) VALUES (1, 'POKERKING', 'WPN');

CREATE TABLE hero_account (
    room_id   smallint NOT NULL REFERENCES room,
    nickname  text NOT NULL,
    PRIMARY KEY (room_id, nickname)
);

CREATE TABLE player (
    player_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    room_id      smallint NOT NULL REFERENCES room,
    nickname     text NOT NULL,
    external_id  uuid,
    country      char(3),
    canonical_id bigint REFERENCES player,
    first_seen   timestamptz,
    last_seen    timestamptz,
    UNIQUE (room_id, nickname)
);
CREATE UNIQUE INDEX player_ext_uq ON player (room_id, external_id) WHERE external_id IS NOT NULL;

CREATE TABLE tournament (
    tournament_id   bigint PRIMARY KEY,
    room_id         smallint NOT NULL REFERENCES room,
    name            text,
    started_at      timestamptz,
    finished_at     timestamptz,
    buy_in          bigint,
    fee             bigint,
    currency        char(3),
    prize_pool      bigint,
    player_count    integer,
    format          smallint,
    is_ko           boolean,
    ko_kind         smallint,
    source_file     text
);

CREATE TABLE tournament_result (
    tournament_id   bigint NOT NULL REFERENCES tournament,
    player_id       bigint NOT NULL REFERENCES player,
    finish_position integer,
    prize           bigint,
    ticket_value    bigint,
    bounty_won      bigint,
    entry_no        smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (tournament_id, player_id, entry_no)
);

CREATE TABLE table_instance (
    table_instance_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    room_id           smallint NOT NULL REFERENCES room,
    game_kind         smallint NOT NULL,
    external_game_id  text NOT NULL,
    external_table_id text NOT NULL,
    table_name        text,
    tournament_id     bigint,
    max_seats         smallint NOT NULL,
    currency          char(3) NOT NULL,
    scale             smallint NOT NULL,
    UNIQUE (room_id, external_game_id, external_table_id)
);

CREATE TABLE hands (
    hand_pk           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    room_id           smallint NOT NULL,
    external_hand_id  bigint NOT NULL,
    table_instance_id bigint NOT NULL REFERENCES table_instance,
    played_at         timestamptz NOT NULL,
    game_kind         smallint NOT NULL,
    max_seats         smallint NOT NULL,
    players_dealt     smallint NOT NULL,
    button_seat       smallint NOT NULL,
    sb bigint NOT NULL, bb bigint NOT NULL, ante bigint NOT NULL DEFAULT 0,
    tourney_level     smallint,
    total_pot bigint NOT NULL, rake bigint NOT NULL DEFAULT 0, jp_fee bigint NOT NULL DEFAULT 0,
    board_count       smallint NOT NULL DEFAULT 1,
    hero_seat         smallint,
    flags             integer NOT NULL DEFAULT 0,
    context_version   smallint NOT NULL,
    UNIQUE (room_id, external_hand_id)
);
CREATE INDEX hands_played_at_brin ON hands USING brin (played_at);
CREATE INDEX hands_table_idx     ON hands (table_instance_id, played_at);

CREATE TABLE hand_raw (
    hand_pk     bigint PRIMARY KEY REFERENCES hands ON DELETE CASCADE,
    body        bytea NOT NULL,
    codec       smallint NOT NULL DEFAULT 0,
    source_file text NOT NULL,
    file_offset bigint NOT NULL
);
ALTER TABLE hand_raw ALTER COLUMN body SET STORAGE EXTERNAL;

CREATE TABLE hand_players (
    hand_pk      bigint NOT NULL REFERENCES hands ON DELETE CASCADE,
    seat         smallint NOT NULL,
    player_id    bigint NOT NULL REFERENCES player,
    position     smallint NOT NULL,
    start_stack  bigint NOT NULL,
    stack_bb_x10 smallint NOT NULL,
    hole_card1   smallint, hole_card2 smallint,
    hole_class   smallint,
    invested     bigint NOT NULL,
    collected    bigint NOT NULL,
    net_won      bigint NOT NULL,
    net_won_bb_x100 integer NOT NULL,
    rake_share   bigint NOT NULL DEFAULT 0,
    fact_bits    bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (hand_pk, seat)
);
CREATE INDEX hand_players_player_idx ON hand_players (player_id, hand_pk);

CREATE TABLE hand_actions (
    hand_pk    bigint NOT NULL REFERENCES hands ON DELETE CASCADE,
    seq        smallint NOT NULL,
    street     smallint NOT NULL,
    seat       smallint NOT NULL,
    action     smallint NOT NULL,
    amount     bigint NOT NULL,
    to_amount  bigint NOT NULL,
    pot_before bigint NOT NULL,
    is_all_in  boolean NOT NULL DEFAULT false,
    PRIMARY KEY (hand_pk, seq)
);

CREATE TABLE hand_boards (
    hand_pk  bigint NOT NULL REFERENCES hands ON DELETE CASCADE,
    board_no smallint NOT NULL,
    c1 smallint, c2 smallint, c3 smallint, c4 smallint, c5 smallint,
    PRIMARY KEY (hand_pk, board_no)
);

CREATE TABLE hand_decisions (
    hand_pk          bigint NOT NULL REFERENCES hands ON DELETE CASCADE,
    seq              smallint NOT NULL,
    seat             smallint NOT NULL,
    player_id        bigint NOT NULL,
    street           smallint NOT NULL,
    position         smallint NOT NULL,
    facing           smallint NOT NULL,
    bet_level        smallint NOT NULL,
    my_last_level    smallint NOT NULL,
    to_call          bigint NOT NULL,
    pot_before       bigint NOT NULL,
    eff_stack        bigint NOT NULL,
    players_in       smallint NOT NULL,
    players_behind   smallint NOT NULL,
    num_limpers      smallint NOT NULL,
    num_callers      smallint NOT NULL,
    ctx_bits         bigint NOT NULL,
    chosen           smallint NOT NULL,
    chosen_amount    bigint NOT NULL,
    size_pct         smallint,
    is_all_in        boolean NOT NULL,
    hand_strength    smallint,
    board_texture    smallint,
    stack_bucket     smallint NOT NULL,
    PRIMARY KEY (hand_pk, seq)
);
CREATE INDEX hand_decisions_player_idx ON hand_decisions (player_id, street, hand_pk);

CREATE TABLE player_stat_agg (
    player_id    bigint   NOT NULL,
    stat_id      integer  NOT NULL,
    game_kind    smallint NOT NULL,
    dealt_bucket smallint NOT NULL,
    position     smallint NOT NULL,
    stack_bucket smallint NOT NULL,
    cases        integer  NOT NULL,
    hits         integer  NOT NULL,
    sum_value    bigint   NOT NULL DEFAULT 0,
    PRIMARY KEY (player_id, stat_id, game_kind, dealt_bucket, position, stack_bucket)
);

CREATE TABLE stat_definition (
    stat_id     integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code        text NOT NULL UNIQUE,
    title       text NOT NULL,
    scope       smallint NOT NULL,
    definition  jsonb NOT NULL,
    version     integer NOT NULL DEFAULT 1,
    is_builtin  boolean NOT NULL DEFAULT false,
    is_active   boolean NOT NULL DEFAULT true
);

CREATE TABLE agg_watermark (
    stat_id      integer PRIMARY KEY REFERENCES stat_definition ON DELETE CASCADE,
    def_version  integer NOT NULL,
    last_hand_pk bigint  NOT NULL
);

CREATE TABLE hud_profile (
    profile_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text NOT NULL, game_kind smallint, layout jsonb NOT NULL
);

CREATE TABLE player_note (
    note_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    player_id  bigint NOT NULL REFERENCES player,
    created_at timestamptz NOT NULL DEFAULT now(),
    body       text NOT NULL,
    color_tag  smallint
);
CREATE INDEX player_note_player_idx ON player_note (player_id);

CREATE TABLE import_state (
    source_file text PRIMARY KEY,
    byte_offset bigint NOT NULL,
    size        bigint NOT NULL,
    mtime       timestamptz NOT NULL
);

CREATE TABLE import_error (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    source_file text,
    file_offset bigint,
    message     text,
    body        text,
    seen_at     timestamptz DEFAULT now(),
    UNIQUE (source_file, file_offset)
);
